"use strict";
// Citizens VCRM demo: the process overview and the Process FAQ. Loaded in order by the page; all files share one scope.
/* ---------- how it works: contact to Closed Won ---------- */
const FI = (p) => `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`;
const PROCESS_INTRO = "We have a six stage process for taking a person who may want to invest in our work from the qualification stage through receiving their investment.";
const FLOW = [
  { stage: "Contact", icon: FI('<circle cx="12" cy="8" r="4"/><path d="M4 21c1-4 4.5-6 8-6s7 2 8 6"/>'), means: "A person we know: a prospect, an investor or an ally.",
    move: ["Add the contact: a name plus an email or a mobile number.", "Create an opportunity for them. It starts in Qualification."], tryLine: "Let's add a contact" },
  { stage: "Qualification", icon: FI('<circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/>'), means: "Is this person a real prospect for us?",
    move: ["Accepted: an officer owns the opportunity.", "Rated: a capacity rating, A to D, is on the contact.", "Talked to: a substantive call or meeting is logged.", "Confirmed: the officer taps Move to Cultivation, or defers with a reason and an optional Reconsider on date."], tryLine: "Log a meeting" },
  { stage: "Cultivation", icon: FI('<path d="M12 21s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 11c0 5.6-7 10-7 10z"/>'), means: "Building the relationship until the investor is ready to be asked.",
    move: ["Add a planned ask: entity, campaign, planned date and amount. A reminder task is due seven days before the planned date."], note: "An ask can be planned only once the opportunity is in Cultivation.", tryLine: "Plan an ask" },
  { stage: "Ask Planning", icon: FI('<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/>'), means: "The ask is planned, with an amount and a date.",
    move: ["Make the ask, then record it with the investor's response: accepted, countered, awaiting or declined."], note: "A declined ask closes the opportunity as Closed Lost, with a reason.", tryLine: "Record an ask" },
  { stage: "Ask Made", icon: FI('<path d="M21 12a8 8 0 0 1-11.6 7.1L4 21l1.9-5.4A8 8 0 1 1 21 12z"/>'), means: "The investor has been asked. We wait for their answer or the pledge details.",
    move: ["After a yes, a Follow up on agreed pledge task reminds the officer to get the confirmation.", "Record the pledge once the investor confirms it by email, phone or in person."], note: "A yes to an outright ask moves the opportunity straight to Commitment. If a gift arrives before any pledge, Record gift records it as an implied commitment: the opportunity passes through Commitment and closes as Closed Won.", tryLine: "Record a pledge" },
  { stage: "Commitment", icon: FI('<path d="M4 20h16M6 16l9.5-9.5a2.1 2.1 0 0 1 3 3L9 19H6z"/>'), means: "The investor has committed: a yes to an outright ask, a pledge they confirmed, or an implied commitment from a gift that arrived first. We wait for the gift, or the first gift on a pledge.",
    move: ["Record the first gift with Record gift when it comes in; it is applied to the pledge."], tryLine: "Record a gift" },
  { stage: "Closed Won", icon: FI('<path d="M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0z"/><path d="M17 5h3v2a3 3 0 0 1-3 3M7 5H4v2a3 3 0 0 0 3 3"/>'), means: "The money is in. Later installments are tracked on the pledge.", move: [] }
];
const flowIndex = (name) => FLOW.findIndex(f => f.stage.toLowerCase() === String(name || "").toLowerCase().replace(/^closed$/, "closed won"));
function flowScreen() {
  const at = S.flowAt == null ? -1 : S.flowAt;
  return topbar("How it works", S.flowBack || "home") + `<main>
  <section class="panel"><div class="flowhero"><h2 style="margin:0;font-size:18px">From first contact to Closed Won</h2>
    <p>Every opportunity moves through the same stages. Tap a stage to see what has to happen before it can move on.</p>
    <button class="btn blue" data-say="Walk me through the process" data-nohint="1">${mic(18)} Hear the overview</button></div></section>
  <section class="panel"><ol class="flowpath">${FLOW.map((f, i) => {
    const on = i === at, past = at > -1 && i < at;
    return `<li class="fstep ${on ? "on" : ""} ${past ? "past" : ""}" id="fstep${i}"><div class="fdot">${f.icon}</div>
    <div class="fcard" data-act2="flowstep" data-i="${i}"><h3>${esc(f.stage)}<small>${i === 0 ? "Start" : i === FLOW.length - 1 ? "Done" : "Stage " + i}</small></h3><div class="fm">${esc(f.means)}</div>
    ${on && (f.move.length || f.note) ? `<div class="fmove">${f.move.length ? `<b>To move on</b><ul>${f.move.map(m => `<li>${esc(m)}</li>`).join("")}</ul>` : ""}${f.note ? `<div class="fnote">${esc(f.note)}</div>` : ""}
      ${f.tryLine ? `<button class="btn out" data-say="${esc(f.tryLine)}">${mic(16)} Try it: “${esc(f.tryLine)}”</button>` : ""}</div>` : ""}</div></li>`; }).join("")}</ol></section>
  </main>`;
}
function highlightStage(i) {
  S.flowAt = i; if (S.screen !== "flow") S.screen = "flow"; save(); render();
  const el = document.getElementById("fstep" + i); if (el) el.scrollIntoView({ block: "center", behavior: "smooth" });
}
/* Process FAQ drawn from the Chief Gift Officer's Guide; Grok answers process questions only from this and FLOW. */
const FAQ_TEXT = "Citizens Alliance Fundraising - Process FAQ for the voice assistant\nSource: \"Citizens Alliance Fundraising: A Chief Gift Officer's Guide to Contacts, Opportunities and Stages\" (DRAFT). The screens in the guide are mockups; names and numbers in its examples are invented.\n\n## Roles and who can do what\n\nQ: What roles does the guide describe?\nA: Gift officers, who own Contacts and opportunities and record the work, and the Chief Gift Officer, who manages the gift officers and sees the whole team. Administrators are also mentioned for correcting money and changing organization settings.\n\nQ: Who is the primary gift officer?\nA: The primary gift officer is the staff member who owns the opportunity and whose home page it appears on.\n\nQ: Who can assign an opportunity to another officer?\nA: Someone other than the owning officer, usually the Chief Gift Officer, can create an opportunity and assign it to an officer. That is Path B, and the officer must then accept or decline it.\n\nQ: Who can choose the owning officer on a new Contact?\nA: A Chief Gift Officer chooses the owning gift officer on the New contact form. For anyone else it defaults to the officer creating the contact.\n\nQ: Who can set the Ally - Do Not Solicit flag?\nA: Whoever creates the Contact can tick it on the New contact form. After that, only the Chief Gift Officer can set it.\n\nQ: Who can clear the Ally - Do Not Solicit flag?\nA: Either the person who set it or the Chief Gift Officer can clear it, in the Preferences panel. Every change is logged with who made it and when.\n\nQ: Who can tick Do Not Contact?\nA: Any officer can tick Do Not Contact when the person asks not to be contacted.\n\nQ: Who can clear Do Not Contact?\nA: Only a Chief Gift Officer can clear Do Not Contact. Every change is logged, with who set it, when and the source.\n\nQ: Who can edit or reverse a saved ask, pledge or gift?\nA: Only the Chief Gift Officer or an administrator, and they must give a reason. History keeps the before and after.\n\nQ: Who approves moving a stage back?\nA: The officer chooses Move stage back from the Actions menu and gives a reason, and the Chief Gift Officer approves it before the stage moves. History records both.\n\nQ: Who can change organization settings such as alert day counts?\nA: Only the Chief Gift Officer or an administrator can change these settings, and every change is recorded with who made it and when.\n\nQ: Who can see a deferral reason?\nA: When an officer defers the move to Cultivation, the reason is visible to the Chief Gift Officer.\n\nQ: Who reviews planned asks?\nA: The Chief Gift Officer. They are notified when the organization requires review above a threshold or when the officer requests it.\n\nQ: What permissions does the voice assistant use?\nA: The assistant acts with the officer's own permissions.\n\n## Contacts\n\nQ: What is a Contact?\nA: A Contact is a person: an investor, a prospect, a board member, a spouse or an advisor. Every individual is a Contact, whether or not they give.\n\nQ: What does the New contact form ask for?\nA: Four things: name, email, mobile phone and, for a Chief Gift Officer, which officer will own the contact. First and last name are both required.\n\nQ: Does a contact need both an email and a mobile number?\nA: No, it needs at least one of them. Create and open stays unavailable until an email or a mobile number is filled in.\n\nQ: What happens to the mobile number entered on the New contact form?\nA: It is saved as the contact's primary phone.\n\nQ: What is the How we met line?\nA: It is an optional line on the New contact form, and whatever is typed there becomes the contact's first note.\n\nQ: How are duplicates caught?\nA: As the officer types, the name and email are checked against existing contacts, so duplicates are caught before they are created. When adding by voice, the duplicate check runs first and a possible match appears before anything else.\n\nQ: What does Create and open do?\nA: It saves the contact and lands on the new Contact record, two clicks from starting an opportunity. Everything else about the person is entered later, on the Details tab.\n\nQ: What is in the Preferences row on the New contact form?\nA: It is collapsed by default and holds Email permitted, Phone calls permitted, Texting permitted and Ally - Do Not Solicit.\n\nQ: What are the default communication permissions on a new contact?\nA: Email permitted and Phone calls permitted are both on by default. Texting permitted is off by default until the person agrees to receive texts.\n\nQ: What is recorded with each permission?\nA: Each permission records who set it, when, and how the person told us: in person, by email, through an unsubscribe link or on a form.\n\nQ: Can I text a contact?\nA: Only once Texting permitted is on, which happens when the person agrees to receive texts. The guide does not describe a texting button or text-sending feature beyond this permission flag.\n\nQ: What does the Contact header show?\nA: The name, the giving status, the capacity rating, and flags for whether email, calls and texts are permitted.\n\nQ: What are the giving cards?\nA: Three cards showing lifetime giving, the last gift and any open pledge balance. Nobody types these; they are kept up to date from the gift records.\n\nQ: What tabs does the Contact record have?\nA: Activities, Opportunities, Details and Files. The Activities tab opens first.\n\nQ: What is the quick-add bar?\nA: It logs a call, meeting, task, note, email or interaction report in one click.\n\nQ: What do the email and phone buttons on the Contact do?\nA: Email opens a popover with Write in Gmail, which opens a Gmail compose window addressed to the investor, or Copy. Phone lists the contact's numbers with a Call button that hands the number to the officer's phone or computer, then opens the call form already filled in.\n\nQ: What if there is no email on file or email is not permitted?\nA: With no email on file the popover offers Add email. If email is not permitted, it has no Write button.\n\nQ: What does the call form fill in?\nA: The contact, direction, time, officer and number. Save call logs the interaction against the contact, and Did not connect records a missed attempt.\n\nQ: What is the giving status and who sets it?\nA: It is Prospect, Investor or Lapsed, set by the system from gift history. Nobody types it.\n\nQ: What makes someone a Prospect, Investor or Lapsed?\nA: Prospect means no gifts, Investor means they gave within the lapsed period, and Lapsed means their last gift is older than the lapsed period.\n\nQ: How long until an investor counts as lapsed?\nA: 24 months. The lapsed period is a setting per organization, and 24 months was settled with the customer.\n\nQ: Does creating an opportunity change the giving status?\nA: No. The giving status comes from gift history, so a contact with an open opportunity but no gifts is still a Prospect.\n\nQ: Are households supported?\nA: Not yet. Household support on the Contact screen comes in a later phase, built on the CRM's Accounts module, and households are not in search for this phase.\n\n## Adding a contact by voice\n\nQ: Can I add a contact by voice?\nA: Yes, on a phone. Tap the mic and say who the person is, how to reach them, what they agreed to and how you met, and the assistant opens the New contact form filled in from what was said.\n\nQ: What if I don't give an email or mobile number by voice?\nA: The assistant asks for each one and explains that the contact needs at least one. Without either, the contact cannot be saved.\n\nQ: What does Check this mean on a voice draft?\nA: It marks a field the assistant is unsure of, typically a spoken email address, so the officer checks it.\n\nQ: How are permissions recorded when a contact is added by voice?\nA: The permissions record that the officer was told in person and entered them by voice.\n\nQ: Can voice set the capacity rating or the do-not flags?\nA: Voice never fills the capacity rating. It can tick Ally - Do Not Solicit or Do Not Contact only when the officer says so.\n\nQ: What happens when I save a voice-drafted contact?\nA: Nothing is saved until the officer taps Save contact. That opens the new Contact record with Contact saved, an Undo, and suggested next steps such as logging the meeting as an interaction, creating an opportunity or rating capacity, and History marks the contact as created by voice.\n\n## Ally - Do Not Solicit\n\nQ: What is Ally - Do Not Solicit?\nA: A tick box for a Contact who supports the organization but must not be asked for a gift, such as a board member the director handles personally, a volunteer leader or a partner.\n\nQ: What changes on the Contact when the ally flag is ticked?\nA: The Ally label replaces the giving status in the header, a Do not solicit flag joins the email, call and text flags, and the Create opportunity button disappears.\n\nQ: Can an ally still help with fundraising?\nA: Yes. An ally can be added to other people's opportunities as a participant, such as an Introducer or Advisor, and can join an ask.\n\nQ: Can an ally ever be asked for a gift?\nA: Yes. Clearing the flag, for example when a board member is to be approached during a campaign, restores the giving status and the Create opportunity button at once. This was settled with the customer on October 17, 2026.\n\nQ: Where do allies appear in the Contacts list?\nA: Only in the My allies (Do Not Solicit) saved view, never in the three giving views.\n\nQ: Is the ally flag logged?\nA: Yes. Every change to the flag, at entry or later, is logged with who made it and when.\n\nQ: Does the ally flag stop all contact?\nA: No. Ally - Do Not Solicit stops asks but not contact. Do Not Contact is the separate flag that stops all outreach.\n\n## Do Not Contact\n\nQ: What is Do Not Contact?\nA: A separate tick box in the Preferences panel for a person who has asked not to be contacted at all.\n\nQ: What does Do Not Contact do?\nA: While ticked, it overrides the email, call and text permissions, the email and phone buttons offer no Write or Call, bulk email leaves the person out, the voice assistant will not draft a message to them, and Create opportunity is hidden.\n\nQ: Does Do Not Contact remove the person from the file?\nA: No. The person stays in the file with their giving history and can still be a participant on someone else's opportunity.\n\nQ: Who can set and clear Do Not Contact?\nA: Any officer can tick it when the person asks; only a Chief Gift Officer can clear it. It records who set it, when and the source, and every change is logged.\n\n## Capacity ratings\n\nQ: What is a capacity rating?\nA: An A to D estimate of what the investor could give, made by the officer from research and conversation.\n\nQ: What do the capacity ratings mean?\nA: A is $250K and above, B is $100K to $250K, C is $25K to $100K, and D is under $25K. These are the starting ranges, and each organization can change them.\n\nQ: Where is the capacity rating set?\nA: In the Contact header; clicking Not rated opens the rating list.\n\nQ: What is stored with the rating?\nA: Who set it, when, and an optional source note such as a wealth screening or a conversation. It also shows on the opportunity.\n\nQ: Is a capacity rating required?\nA: Yes, before an opportunity can leave Qualification for Cultivation, because the ask amount, the pipeline and the portfolio review all rest on it.\n\nQ: Is the suggested ask amount pre-filled from the rating?\nA: No. The amount is blank by default, with capacity and giving history shown only as a hint, because the officer owns the number.\n\n## Interactions and interaction reports\n\nQ: What is an interaction?\nA: Any encounter with an investor or participant: an email, a call, a video call or an in-person meeting.\n\nQ: What is a substantive interaction?\nA: A real conversation with the investor or a participant about the relationship or the gift. Research notes and emails are not substantive interactions.\n\nQ: What is a visit?\nA: A meeting that was held and substantive.\n\nQ: What is an interaction report?\nA: The record of a held call or meeting: whether it was substantive, the outcome, the next step and notes. The report appears once the status is Held and is filled in on the same form.\n\nQ: What are the meeting outcomes?\nA: Interested, continue cultivation; Ask made; Ask accepted; Not now, revisit; Not interested; Referred elsewhere. The organization can edit the list, and it keeps these defaults for now.\n\nQ: What meeting types are there?\nA: The guide shows Visit as a meeting type and says the meeting-type list keeps its defaults for now, but it does not list the other types.\n\nQ: When is a next step required?\nA: The next step and its due date are required on any held, substantive interaction, unless the outcome is Not interested or Referred elsewhere.\n\nQ: What happens if the outcome is Not interested or Referred elsewhere?\nA: No next step is needed, and the save offers Close as lost with a reason instead.\n\nQ: Is the next step a fixed list?\nA: No, it is free text with suggestions: Schedule a visit, Send a proposal, Follow-up call, Invite to event, Introduce to leadership and Thank-you note. Anything else is accepted.\n\nQ: What happens to a next step when the report is saved?\nA: Each next step becomes exactly one Task on the opportunity, named with its text and due on its date. It then appears under Next steps on the Contact, on the Opportunity and on the home page.\n\nQ: What if I save the same report twice?\nA: Saving the same report again, or confirming a voice draft twice, updates its task and never creates a second task, ask or pledge.\n\nQ: Does a meeting outcome change the stage?\nA: No. A meeting outcome never sets a stage. Ask made on an outcome form marks the planned Ask as made, and the stage follows from the Ask.\n\nQ: How do Google Calendar meetings get into the system?\nA: Meetings arrive on the Activities tab from Google Calendar on their own, and the home page shows the week's meetings with who has accepted the invitation.\n\nQ: What happens after a calendar meeting ends?\nA: Ten minutes after the end time, a push notification and an email ask how the meeting went, such as How did lunch with Margaret and David go?, and open a thirty-second form: held or not, meeting type, outcome, next step and dictated notes.\n\nQ: Do notes typed in the calendar event come through?\nA: Yes. Notes typed into the calendar event itself flow in the same way.\n\nQ: How are Gmail emails handled?\nA: Emails from Gmail are filed against the contact and, where the match is certain, against the opportunity.\n\nQ: What is the Needs notes pill?\nA: A held meeting with no outcome shows a Needs notes pill on the activity panel and a count on the home page, so the Chief Gift Officer sees who is behind.\n\nQ: Can I fill an interaction report by voice?\nA: Yes. On a phone the assistant drafts the fields from what was said, each filled field carries a small microphone and light-blue edge, and the officer checks them and taps Save. The saved interaction is marked via voice in History.\n\nQ: What if the assistant is unsure of a field in a voice report?\nA: It gets an amber edge and Check this, and is never guessed silently. For example, \"next Tuesday\" read as a date is flagged.\n\nQ: Can the assistant make up a new outcome?\nA: No. It matches the outcome to the organization's short list and cannot invent a new one.\n\nQ: Can I see what I said in a voice report?\nA: Yes. View transcript shows the officer's own words behind a collapsed link, so the filled fields come first.\n\n## Tasks and next steps\n\nQ: What is a Task?\nA: A to-do item with an owner, a due date and a link to the Contact or opportunity, kept in the CRM's Tasks module. Ticking one off marks it done.\n\nQ: Where do Tasks come from?\nA: Each next step becomes exactly one Task, an officer can add a Task directly with Add a task, and the system creates some itself, such as Follow up on agreed pledge and the reminder seven days before a planned ask date.\n\nQ: What are the status choices for a Task?\nA: To do, In progress, Waiting (on someone, with a check-back date; the default check-back is a week away) and Done. By voice, say for example mark it done, I've started on it, or waiting on Elena until Friday; the assistant reads back the task, who it is for and the due date, and changes it only after you say yes. In the app, tap the circle to mark a Task done (Undo is offered) or tap the status pill to pick another status.\n\nQ: What shows in the Next steps panel?\nA: Open Tasks, including those from next steps and those added directly, plus upcoming meetings.\n\n## Opportunities\n\nQ: What is an Opportunity?\nA: One investor's path toward one gift, carrying the stage, intended amount, entity, ask, pledge and gifts. In fundraising practice it is the prospect plan or moves management record.\n\nQ: How many open opportunities can an investor have?\nA: At most one at a time. Create opportunity appears only when there is none, and the next gift is sought on a new opportunity once the current one closes.\n\nQ: What does Create opportunity ask for?\nA: Only a name, suggested in the pattern Last, First - Year, which the officer can change, and the owning officer.\n\nQ: What is left blank on a new opportunity?\nA: The entity of interest, the campaign and the intended amount. The officer fills them in during Cultivation, and the planned ask supplies them at Ask Planning if still blank.\n\nQ: Who becomes the primary participant?\nA: The contact automatically becomes the opportunity's primary participant, in the Investor role.\n\nQ: Is Contact information copied onto the opportunity?\nA: No. Nothing is copied, so a changed phone number or address is changed in one place.\n\nQ: What is Path A?\nA: The officer creates the opportunity themselves from the Contact, and it is accepted the moment it is saved.\n\nQ: What is Path B?\nA: Someone else, usually the Chief Gift Officer, creates the opportunity and assigns it to the officer. It waits in the officer's Awaiting my review list, counted in the top-bar badge and Needs attention, until the officer accepts or declines it.\n\nQ: What can happen on an unaccepted opportunity?\nA: Nothing else, deliberately. The officer must accept it or decline it with a reason.\n\nQ: What can I set while accepting?\nA: The entity of interest and a first action, both optional.\n\nQ: What does declining require?\nA: A reason.\n\nQ: What are participants?\nA: People connected to an opportunity with a role: Investor, Household member, Decision maker, Advisor, Influencer, Introducer, Organizational contact or Other. One participant is marked primary, and roles are marked investor side or organization side.\n\nQ: Who can be a participant?\nA: Anyone. Participants are a list with roles, open to board members, other investors and contractors, and even allies and Do Not Contact people.\n\nQ: What does the Opportunity record show?\nA: A header with the stage bar, four money tiles (Potential, Asked, Committed, Received), and tabs for Fundraising, Activities, Files and History.\n\nQ: What are the money tiles?\nA: Potential, Asked, Committed and Received, each kept up to date by the system.\n\nQ: What is the blue stage button?\nA: One button for the stage's main next step: Log interaction at Qualification (Accept while awaiting review), Add planned ask at Cultivation, Record the ask at Ask Planning, Record pledge at Ask Made (Record gift for an outright gift ask), and Record gift at Commitment (applied to the pledge). A closed opportunity has none.\n\nQ: What is in the Actions menu?\nA: Every record action, including Add planned ask, Record pledge, Record gift and Move stage back. The stage button opens the same form as the matching Actions item.\n\nQ: What is the Activities tab on an opportunity?\nA: The Contact's activity panel filtered to this opportunity. An interaction report started from the Contact is linked to the open opportunity automatically.\n\n## The stages overall\n\nQ: What are the stages?\nA: Qualification, Cultivation, Ask Planning, Ask Made, Commitment, then Closed Won or Closed Lost.\n\nQ: Can I edit the stage bar by hand?\nA: No. Qualification and the move to Cultivation are confirmed by the officer; from Ask Planning onward, saving an Ask, a Pledge or a Gift moves the stage.\n\nQ: Why is there no Identification stage?\nA: An identified person is just a Contact with giving status Prospect and no open opportunity. Identification lives in the Contacts list, My prospects and the capacity rating.\n\nQ: Why is there no Stewardship stage?\nA: Stewardship never ends and belongs to the investor, not one gift. It lives on the Contact, and the next gift is a new opportunity at Qualification.\n\nQ: How is the stage shown?\nA: As a six-chevron bar on the Opportunity and, read-only, on the Contact: completed stages light blue, current stage dark blue, and Qualification dashed while awaiting acceptance.\n\n## Qualification\n\nQ: How does an opportunity enter Qualification?\nA: When an officer creates it (Path A) or accepts it (Path B).\n\nQ: What are the criteria to leave Qualification?\nA: Four: Accepted, Rated with a capacity rating on the Contact, Talked to through a held substantive call or meeting, and Confirmed by the officer.\n\nQ: Do I need to log an interaction before I can move an opportunity to Cultivation?\nA: Yes. Move to Cultivation needs a capacity rating on the Contact and a substantive interaction recorded in an Interaction report. The app refuses the move until both are there, then shows the Ready for Cultivation alert.\n\nQ: Can I move to Cultivation without a substantive interaction?\nA: No. A substantive interaction (a held call or meeting that moved the relationship forward, marked substantive on its Interaction report) is required, together with a capacity rating.\n\nQ: Do emails or research notes count toward Talked to?\nA: No. Only a call or meeting recorded as held and marked Substantive counts.\n\nQ: What happens when the first three criteria are met?\nA: The stage bar offers Move to Cultivation? and the opportunity shows in Needs attention as Ready for Cultivation, with a green alert. Cultivation is drawn dashed as available.\n\nQ: What are my choices at the Move to Cultivation prompt?\nA: Move to Cultivation, with one click, or Defer with a reason and an optional Reconsider on date.\n\nQ: What does deferring do?\nA: It keeps the opportunity in Qualification and is recorded in History. The prompt and the Needs attention row go away, but Cultivation stays available on the stage bar for a one-click move later.\n\nQ: When does a deferred prompt come back?\nA: On the Reconsider on date or after the next substantive interaction, whichever comes first.\n\nQ: Is this the only stage move the system asks me to confirm?\nA: Yes. It is the only place the system asks the officer to confirm a stage.\n\n## Cultivation\n\nQ: What happens in Cultivation?\nA: Visits, calls, tours, introductions and proposal drafts, each recorded as an interaction. The officer keeps the capacity rating and the Potential amount current.\n\nQ: Does anything in Cultivation move the stage automatically?\nA: No. The opportunity moves to Ask Planning only when the officer plans the ask.\n\nQ: How do I start planning an ask?\nA: Choose Add planned ask from the blue stage button, the Actions menu, or the button in the empty Ask area of the Fundraising tab. All three open the Add planned ask form.\n\nQ: When is Add planned ask offered?\nA: Only while no ask is planned or made on the opportunity, which keeps one open ask per opportunity.\n\n## Ask Planning\n\nQ: What are the required fields on a planned ask?\nA: Four: the entity, the campaign, the planned ask date and the amount.\n\nQ: What are the entity choices?\nA: Citizens Alliance C3, C.A. of America Action C4, C.A. Fed PAC, C.A. Idaho C4, C.A. Idaho PAC, C.A. North Dakota C4, C.A. North Dakota State PAC, C.A. North Dakota Fed PAC, C.A. New Hampshire C4, C.A. Pennsylvania C4 and C.A. Pennsylvania State PAC.\n\nQ: What are the campaign choices?\nA: It depends on the entity. Every entity can take National. A state entity can also take its own state campaign: Idaho, North Dakota, New Hampshire or Pennsylvania. The three national entities (C3, America Action C4 and Fed PAC) take National only.\n\nQ: What are the optional fields on a planned ask?\nA: The ask type (outright, pledge over years or planned gift, defaulting to Outright), the gift officer making the ask (defaulting to the opportunity's gift officer), the participants in the ask, attachments, and Manager review.\n\nQ: Is there a confirmation prompt when I save the planned ask?\nA: No. Saving is the officer's declaration of intent, and cancelling changes nothing.\n\nQ: What does saving the planned ask do?\nA: The stage moves to Ask Planning, the Asked tile shows the amount marked Planned in grey, a reminder task is set seven days before the planned date, and if review is required or requested the Chief Gift Officer is notified and the ask shows Review requested until approved.\n\nQ: What does the hint band warn about?\nA: A conflict between the planned channel and the investor's communication preference, or an open pledge balance on another opportunity.\n\nQ: Is manager review required?\nA: It is a setting per organization: optional, or required above an amount. This organization starts with review optional, so the officer requests it when wanted.\n\nQ: What does the planned ask drive?\nA: The ask calendar for the next 30, 60 and 90 days, the Chief Gift Officer's weighted pipeline, and the asks-expected-this-month list.\n\nQ: What if I reschedule a planned ask?\nA: The stage stays the same and the reschedules are counted, which the Chief Gift Officer can see.\n\n## Ask Made\n\nQ: How do I record that the ask was made?\nA: Log the interaction report from the Activities tab of the Contact or Opportunity, tick This meeting included the ask, and enter the amount asked, the response and what was said. One save records both and moves the opportunity to Ask Made.\n\nQ: What are the response choices?\nA: Awaiting, Accepted, Countered and Declined.\n\nQ: What if the ask was unplanned?\nA: It is recorded the same way and passes through Ask Planning in the same save. The inline fields also ask for the entity and campaign, and the meeting date stands in for the planned date.\n\nQ: What are the statuses of an ask?\nA: Planned, then Made, then Accepted, Countered, Declined or Withdrawn. A follow-on ask from a counter is Agreed, pledge to follow, until the pledge or gift is recorded.\n\nQ: What happens when the investor accepts?\nA: The opportunity stays in Ask Made until the pledge or gift is recorded. A pledge moves it to Commitment, and an outright gift closes it as Closed Won.\n\nQ: How is a counter-offer recorded?\nA: Choose Countered and enter the counter amount; the entity is filled in from the ask and a terms note is optional. The original ask is marked Countered and a follow-on ask at the agreed amount is created as Agreed, pledge to follow.\n\nQ: What do the money tiles show after a counter?\nA: Asked shows the latest ask, with the first ask noted below. Committed stays at zero, with the agreed amount shown as verbal until the pledge is recorded.\n\nQ: What does Agreed, pledge to follow mean?\nA: The investor has said yes to an amount but no pledge or gift is recorded yet. The opportunity stays in Ask Made and shows the amount as verbal.\n\nQ: What is the Follow up on agreed pledge task?\nA: A task that reaches the officer after the pledge reminder interval when a yes has no pledge yet, prompting them to chase the investor's confirmation. The interval is still open with the customer.\n\nQ: What happens if the ask is declined?\nA: With no other open ask, the opportunity moves to Closed Lost with a reason, and the Contact keeps every note.\n\nQ: What happens if the ask is withdrawn?\nA: Withdrawn means the organization pulled the ask, and it returns the opportunity to Cultivation.\n\n## Commitment, pledges and gifts\n\nQ: What does Commitment mean?\nA: The investor has said yes, the organization has recorded a pledge, and no money has arrived yet.\n\nQ: How is a pledge recorded?\nA: With Record pledge: the total, the entity, the schedule such as annual over four years, the first due date, and how the investor confirmed. The system previews the installments before saving.\n\nQ: What does saving a pledge do?\nA: It moves the opportunity to Commitment, sets the Committed tile to the total, and lays out the installments.\n\nQ: What happens to the ask when a pledge is recorded?\nA: If the ask is still awaiting a response, saving the pledge marks it accepted on the same day. A follow-on Agreed ask becomes Accepted.\n\nQ: Are there pledge cards?\nA: No. An investor confirms a pledge by email, by phone or in person.\n\nQ: How is an outright gift recorded?\nA: With Record gift, entered once with its entity, date and payment method. A gift that arrives while the ask is open, with no pledge, is an implied commitment: the opportunity passes through Commitment and closes as Closed Won, and the Commitment panel says Implied.\n\nQ: Does an accepted outright ask go to Commitment?\nA: Yes. A yes to an outright ask is the commitment: the opportunity moves straight to Commitment, shows Agreed, gift to follow, and Record gift closes it as Closed Won when the money arrives. A pledge ask is different: it stays in Ask Made until Record pledge enters the pledge with its schedule.\n\nQ: Is there a Record payment button?\nA: No. There is one money button, Record gift. In Ask Made it records an implied commitment; in Commitment it applies the gift to the pledge.\n\nQ: What is an implied commitment?\nA: A gift received while an ask is open and no pledge was recorded. The check itself is the commitment. It is recorded as a one-payment commitment, paid in full, so every yes passes through Commitment. Pledged shows Pledge; implied shows Committed, implied.\n\nQ: Can a pledge be split across entities?\nA: No. Every pledge and gift has exactly one entity, so a split is recorded as two pledges on the same opportunity.\n\nQ: What is soft credit?\nA: Recognition for someone other than the investor, such as a spouse or introducer. It is entered by a person on the pledge or gift, never automatic.\n\nQ: Can I record a pledge by voice?\nA: Yes. From the Follow up on agreed pledge task, say the confirmed terms; Review opens Record pledge filled in, and the pledge exists only once the officer taps Save there.\n\n## Closed Won, Closed Lost and payments\n\nQ: When does an opportunity become Closed Won?\nA: When money first arrives: a gift with no pledge (an implied commitment) or the first gift on a pledge.\n\nQ: How are later payments tracked?\nA: Each later installment is entered as a gift against the pledge, which tracks collection with its own status.\n\nQ: What are the pledge payment statuses?\nA: Current, Overdue, Paid in full or Written off.\n\nQ: Where do overdue later installments show?\nA: In the officer's Needs attention and on the Contact's open pledge balance, not on the opportunity.\n\nQ: What happens if a pledge is written off?\nA: After payments, the opportunity stays Closed Won and the write-off is recorded with a reason on the pledge. With nothing received, the opportunity moves to Closed Lost with a reason.\n\nQ: What if a pledge is cancelled before any payment?\nA: The opportunity returns to Ask Planning. This is rare and always audited.\n\nQ: Are Closed Won and Closed Lost final?\nA: Yes, they are terminal. The next gift is sought on a new opportunity starting at Qualification.\n\nQ: What about a gift with no opportunity?\nA: It is recorded on the Contact. If there is an open opportunity the officer can link it, closing it as Closed Won; otherwise it counts toward totals, goals and giving status but no pipeline.\n\n## Alerts\n\nQ: What is an alert?\nA: A small coloured label on an opportunity. It appears when its condition is met and clears on its own; nobody adds or removes one by hand. Closed opportunities carry none.\n\nQ: What do alert colours mean?\nA: Red is overdue, act now. Amber needs a decision or review. Green is ready to move or good news. Blue is for information, waiting on someone else.\n\nQ: What is Next step overdue?\nA: Red: the next step's due date has passed and its Task is open. Timed, default zero days of grace.\n\nQ: What is No next step?\nA: Red: the opportunity has no open Task. Event alert.\n\nQ: What is Meeting held, no notes?\nA: Amber: a meeting's date passed with no interaction report. Timed, default two days.\n\nQ: What is No interaction in N days?\nA: Amber: no substantive interaction for N days. Default 60 days; an advisory alert the organization can turn off.\n\nQ: What is the Awaiting my review alert?\nA: Amber, in Qualification: someone else assigned the opportunity and the officer has not accepted it. Event alert.\n\nQ: What is the Ready for Cultivation alert?\nA: Green, in Qualification: all criteria are met and the officer has not moved or deferred it. After a defer it stays hidden until the Reconsider on date or the next substantive interaction.\n\nQ: Are there Cultivation-specific alerts?\nA: No. Only the any-stage alerts apply.\n\nQ: What is Awaiting manager review?\nA: Amber, in Ask Planning: the organization requires review and the planned ask is not yet approved.\n\nQ: What is Planned date passed?\nA: Red, in Ask Planning: the planned ask date has passed and no ask is recorded. Default zero days of grace.\n\nQ: What is Awaiting response?\nA: In Ask Made, shown as Awaiting response with a day count from the ask date. It is blue, turning amber at 14 days by default.\n\nQ: What is the Agreed, pledge to follow verbal alert?\nA: Green, in Ask Made: the response is Accepted or Countered and no pledge or gift is recorded yet.\n\nQ: What is the Follow up on agreed pledge alert?\nA: Amber, in Ask Made: the pledge reminder interval has passed with no pledge. Its default is still open with the customer.\n\nQ: What alerts apply in Commitment?\nA: First payment due soon, blue, within 14 days by default and can be turned off; and First payment overdue, red, after a 15-day grace period to allow for processing. The pledge line is always shown and is not an alert.\n\nQ: Can alerts be turned off?\nA: Only the advisory ones, No interaction in N days and First payment due soon. Red overdue alerts always stay on.\n\n## Home page, lists, saved views and board\n\nQ: What is on the home page?\nA: Four panels in order: Needs attention, Upcoming meetings, then My pipeline and My goals side by side.\n\nQ: What shows in Needs attention?\nA: Unaccepted assignments, held meetings with no notes, Ready for Cultivation opportunities, planned asks past their date, and overdue next steps.\n\nQ: What does My goals count?\nA: Progress against the quarter and year-to-date goals, counted on what has been committed, and whether the officer is on pace.\n\nQ: What are the Contacts saved views?\nA: My prospects, My investors, My lapsed investors and My allies (Do Not Solicit), each limited to the officer's own contacts.\n\nQ: What does the amber Awaiting review pill in Contacts mean?\nA: The contact's opportunity was assigned to this officer and not yet accepted. Clicking the name opens the Contact, not a review screen.\n\nQ: What are the Opportunities saved views?\nA: My open opportunities (the default), Awaiting my review, Asks this quarter, Pledges to record and Closed this year.\n\nQ: Can I drag cards on the board?\nA: No. Cards move only when their records change. The board has one column per open stage, and Closed this year always opens as a list.\n\nQ: What is the top bar?\nA: The blue-grey bar on every screen: menu, Home, Contacts, Search everything, a review badge and the user's initials.\n\n## Chief Gift Officer review and reports\n\nQ: How does the Chief Gift Officer see the whole team?\nA: By switching Needs attention to every officer, and switching Opportunities views from Mine to Team.\n\nQ: How does the Chief Gift Officer see upcoming asks?\nA: Through the ask calendar and pipeline by stage, built from planned asks.\n\nQ: How are goals reported?\nA: Attainment by officer, team, campaign and entity, by fiscal period, from pledges and gifts credited to the officer on the opportunity.\n\nQ: How does the Chief Gift Officer find lapsed investors to reassign?\nA: My lapsed investors, viewed across officers.\n\nQ: What counts toward attainment?\nA: Still open with the customer: which gift types, pledge treatment and soft credit count is undecided.\n\n## Exceptions and corrections\n\nQ: How do I fix a wrong stage?\nA: Usually by fixing the record. Otherwise use Move stage back with a reason, approved by the Chief Gift Officer.\n\nQ: Can I edit a saved pledge amount?\nA: No. Only the Chief Gift Officer or an administrator can edit or reverse saved money, with a reason.\n\n## Voice assistant rules\n\nQ: What is the voice assistant's main rule?\nA: Voice drafts and the officer confirms. Nothing is saved until the officer taps Save.\n\nQ: Does asking a question change anything?\nA: No. A question is answered from the records and changes nothing.\n\nQ: How are voice-saved records marked?\nA: Every record saved from a voice draft is marked via voice in History.\n\nQ: Can I type instead of speaking?\nA: Yes. Type instead lets the request be typed.\n\nQ: Does voice listen for a wake word?\nA: No. It is tap-to-talk; it cannot listen while locked or start from Siri or Google Assistant.\n\nQ: What is the meeting briefing?\nA: A short phone summary drafted from the person's records, with up to three suggested topics. Every line links to its source, and it changes nothing.\n\n## Phone and mobile app\n\nQ: How do I install the app?\nA: It is a mobile web app. On iPhone, use Share then Add to Home Screen; on Android, Install app or Add to Home screen in Chrome.\n\nQ: How do I get notifications?\nA: Add the icon to the home screen and allow notifications when asked.\n\n## Organization settings\n\nQ: What can each organization configure?\nA: Capacity ranges, the outcome list, the lapsed period, review policy, the pledge reminder interval, timed alert day counts, and turning off advisory alerts.\n\nQ: Can an organization change alert wording or colour?\nA: No. Wording, colour and meaning are the same everywhere.\n\nQ: What was day-one history settled as?\nA: All available giving data, about five years. Export file layouts are still open.\n\n## Vocabulary\n\nQ: Appeal?\nA: One specific solicitation, such as a mailing, an email or an event.\n\nQ: Campaign?\nA: A named, time-bound effort to raise a target.\n\nQ: Dashlet?\nA: One panel on the home page.\n\nQ: Entity?\nA: The Citizens Alliance organization that receives the money.\n\nQ: Gift?\nA: Money received, outright or as a pledge payment.\n\nQ: Goal?\nA: A target for an officer, team, campaign or entity for a fiscal period.\n\nQ: Pledge?\nA: A promise to give a stated amount over a stated schedule.\n\nQ: Roll-up?\nA: A system-kept number such as total given, last gift date or open pledge balance.\n\nQ: Saved view?\nA: A list with a filter already applied, chosen from a dropdown.\n\nQ: Review of an ask?\nA: A manager's look at a planned ask before it is made.";
const flowScript = () => FLOW.map(f => `${f.stage}: ${f.means}${f.move.length ? " To move on: " + f.move.join(" ") : ""}${f.note ? " " + f.note : ""}`).join("\n");

const TASK_F = {
  open: ["Open", t => !t.done, "My open tasks"],
  overdue: ["Overdue", t => !!taskAlert(t), "Overdue"],
  week: ["This week", t => !t.done && !!t.due && t.due <= addDays(todayISO(), 7), "Due this week"],
  waiting: ["Waiting", t => taskStatus(t) === "waiting", "Waiting on someone"],
  done: ["Done", t => t.done, "Done"],
};
const taskFk = () => TASK_F[S.tFilter] ? S.tFilter : "open";
function tasksScreen() {
  const fk = taskFk(), F = TASK_F[fk];
  const rows = S.tasks.filter(F[1]).sort(fk === "done" ? (x, y) => (y.doneOn || "").localeCompare(x.doneOn || "") : (x, y) => (x.due || "9999").localeCompare(y.due || "9999"));
  const none = !S.tasks.length ? "No tasks yet. Say “Add a task”, or mention a next step when you log a meeting." : fk === "open" ? "Nothing open. Nice work." : "Nothing here right now.";
  return topbar("Tasks") + `<main><input id="tSearch" class="search" type="search" placeholder="Search tasks" autocomplete="off">${chipRow(TASK_F, fk, "tfilt", S.tasks, "")}<section class="panel"><div class="ph"><h2>${F[2]}</h2><span class="meta">${rows.length}</span></div>
  ${rows.length ? rows.map(t => taskRow(t, true)).join("") : `<div class="empty">${none}</div>`}
  ${fk === "done" ? "" : `<div class="thint">Tap the circle when a task is done, or tap its status to change it. You can also swipe a task left, or just tell ${esc(botName())}.</div>`}</section></main>`;
}
function settingsScreen() {
  return topbar("Settings", "home") + `<main>
  <section class="panel" id="setSave"><div class="ph"><h2>${SAVE_TITLE}</h2></div><div class="sb set">
    <div class="appbtn-tile">${APP_BTN(60)}<span>Citizens VCRM</span></div>
    <div style="font-size:13.5px;color:var(--muted);line-height:1.45;text-align:center">This is the button you'll get. Tap it to open Citizens VCRM like an app, with the mic ready.</div>
    ${saveTip(true)}</div></section>
  <section class="panel"><div class="ph"><h2>Your first name</h2></div><div class="sb set">
    <label for="userName">Your first name (the assistant uses it)<input id="userName" name="vcrm-first-name-y" autocomplete="off" autocorrect="off" spellcheck="false" data-lpignore="true" data-1p-ignore placeholder="For example, Sam" enterkeyhint="done" value="${esc(S.settings.userName || "")}"></label>
    <div style="font-size:12.5px;color:var(--muted);line-height:1.4">This proof of concept saves when you open the app, what you say to the assistant and its replies, what you tap, and what is in each form when you tap Save, how well your connection to the voice service holds up during a conversation, with your first name, a random ID for this phone and your rough location (city), to improve the proof of concept. Your exact location is added to the notes about the voice line only if you turn that on in Settings. No audio is kept. Kept for 90 days.</div>
    <label class="hint-tgl" for="locTgl"><input type="checkbox" id="locTgl" ${S.settings.shareLocation ? "checked" : ""}> Record my location in connection logs: where this phone is, to about 10 metres, is added to each note about the voice line dropping, reconnecting or ending, so weak spots can be found. Off unless you turn it on.</label>
  </div></section>
  <section class="panel"><div class="ph"><h2>Voice assistant</h2></div><div class="sb set">
    <div class="status-line"><span class="dot g"></span> Voice is ready. No key is needed on this phone.</div>
    <button type="button" class="linkbtn" data-act2="help">How to talk to ${esc(botName())} ›</button>
    <label for="voiceSel">Voice<select id="voiceSel">${["ara", "eve", "rex", "sal", "leo"].map(v => `<option value="${v}" ${v === S.settings.voice ? "selected" : ""}>${v[0].toUpperCase() + v.slice(1)}</option>`).join("")}</select></label>
    <label for="formVoiceSel">Voice for the app's own lines (form questions, read-backs)<select id="formVoiceSel"><option value="leo" ${S.settings.formVoice === "same" ? "" : "selected"}>Leo, a different voice, so you can tell the app from ${esc(botName())}</option><option value="same" ${S.settings.formVoice === "same" ? "selected" : ""}>The same voice as ${esc(botName())}</option></select></label>
    <label for="speedSel">Speaking speed<select id="speedSel">${SPEEDS.map(v => `<option value="${v}" ${v === talkSpeed() ? "selected" : ""}>${SPEED_NAMES[v]}</option>`).join("")}</select></label>
    <div style="font-size:12.5px;color:var(--muted);line-height:1.4;margin-top:-4px">You can also just tell ${esc(botName())} to talk faster or slower.</div>
    <label for="botName">Assistant's name<input id="botName" autocomplete="off" autocorrect="off" spellcheck="false" enterkeyhint="done" placeholder="${esc(botName())}" value="${esc(S.settings.botName || "")}"></label>
    <div style="font-size:12.5px;color:var(--muted);line-height:1.4;margin-top:-4px">The assistant introduces itself by this name. Leave it blank to use the voice's name.</div>
    <label class="hint-tgl" for="hintsTgl"><input type="checkbox" id="hintsTgl" ${S.settings.noHints ? "" : "checked"}> Show a hint when I tap an option under “Say things like…”</label>
    ${spookySeason() ? `<label class="hint-tgl" for="spookyTgl"><input type="checkbox" id="spookyTgl" ${S.settings.noSpooky ? "" : "checked"}> Halloween: a spider, pumpkin or ghost crosses the screen now and then, with a spooky sound</label>
    <label class="hint-tgl" for="spookyMode"><input type="checkbox" id="spookyMode" ${spookyMode() ? "checked" : ""}> Spooky mode: a night look, ${esc(botName())} as a haunted-house host, spooky sounds on big moments and more visitors. You can also say “spooky mode” or “normal mode”. Ends on Nov 1.</label>` : ""}
    ${xmasSeason() ? `<label class="hint-tgl" for="xmasTgl"><input type="checkbox" id="xmasTgl" ${S.settings.noXmas ? "" : "checked"}> Christmas: snow, a gift, an elf or a reindeer comes by now and then, with a Christmas sound</label>` : ""}
    ${`<label class="hint-tgl" for="xmasMode"><input type="checkbox" id="xmasMode" ${xmasMode() ? "checked" : ""}> Christmas mode: a white, evergreen and red look with a wreath and a nativity scene on Home, ${esc(botName())} as a warm Christmas host, sleigh bells and Santa's “ho ho ho” on big moments, and more visitors. You can also say “Christmas mode” or “normal mode”.</label>`}
    <div style="font-size:12.5px;color:var(--muted);line-height:1.4">Changes on this screen save as soon as you make them.</div>
  </div></section>
  <section class="panel"><div class="ph"><h2>Start by voice (“Hey ${esc(botName())}”)</h2></div><div class="sb set"><div style="font-size:14px;color:var(--muted);line-height:1.45">On an iPhone you can open ${esc(botName())} by saying “Hey ${esc(botName())}”, with nothing extra to install. The start-up address below opens the app onto one big mic; one tap and the conversation starts (the phone only turns the mic on after a tap).</div>
    <div style="font-size:13.5px;line-height:1.45">1. Copy the start-up address.<br>2. Shortcuts app: + › Add Action › Open URLs, and paste it. Name the shortcut “${esc(botName())}”.<br>3. Settings › Accessibility › Vocal Shortcuts › Set Up: pick that shortcut, type “Hey ${esc(botName())}” and say it three times.<br>4. In the shortcut's details, turn on “Allow Running When Locked”.</div>
    <textarea id="callUrl" readonly style="font:13px/1.35 ui-monospace,Menlo,monospace;height:44px;white-space:pre">${esc(CALL_URL())}</textarea>
    <button class="btn out" data-act2="copycall">Copy the start-up address</button></div></section>
  <section class="panel"><div class="ph"><h2>Share this proof of concept</h2></div><div class="sb set"><div style="font-size:14px;color:var(--muted)">Send the proof of concept to someone, or show a QR code they can scan with their phone camera. Anyone with the link can use the voice assistant.</div>
    <button class="btn blue" data-act2="share">Share link</button><button class="btn out" data-act2="qr">Show QR code</button></div></section>
  <section class="panel"><div class="ph"><h2>Version</h2><span class="meta">${esc(buildLabel())}</span></div><div class="sb"><div style="font-size:14px;color:var(--muted)">The proof of concept updates itself to the newest version when you open it.</div></div></section>
  <section class="panel"><div class="ph"><h2>Restart the proof of concept and reset all settings</h2></div><div class="sb set"><div style="font-size:14px;color:var(--muted)">Removes everything you've added and puts back the example contacts and opportunities. All settings go back to how they started: your first name, the voice, the assistant's name and hints. You'll be asked for a first name again.</div><button class="btn danger" data-act2="restartask">Restart the proof of concept</button></div></section>
  <details class="panel trouble"><summary class="ph"><h2>For support</h2><span class="meta">voice log</span></summary><div class="sb set"><div style="font-size:14px;color:var(--muted)">If the voice misbehaves, tap Copy log and send it to your project contact.</div>
    <textarea id="vlogTxt" readonly style="font:12px/1.35 ui-monospace,Menlo,monospace;height:160px;white-space:pre">${esc(VLOG.slice(-150).join("\n"))}</textarea>
    <button class="btn out" data-act2="copylog">Copy log</button><button class="btn quiet" data-act2="clearlog">Clear log</button></div></details>
  </main>`;
}

setTimeout(() => { if (S.pendingCall) callDoneModal(); }, 600);
function render() {
  applyName();
  const app = document.getElementById("app");
  const s = S.screen;
  app.innerHTML = s === "contacts" ? contactsScreen() : s === "contact" ? contactScreen() : s === "opp" ? (wide() ? boardScreen(true) : oppScreen()) : s === "board" ? boardScreen() : s === "tasks" ? tasksScreen() : s === "settings" ? settingsScreen() : s === "flow" ? flowScreen() : homeScreen();
  const tab = (id, label, icon, also) => `<button class="tab ${s === id || s === also ? "on" : ""}" data-go="${id}">${icon}<span>${label}</span></button>`;
  const I = (p) => `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`;
  document.getElementById("tabs").innerHTML =
    tab("home", "Home", I('<path d="M3 11l9-7 9 7v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>')) +
    tab("contacts", "Contacts", I('<circle cx="12" cy="8" r="4"/><path d="M4 21c1-4 4.5-6 8-6s7 2 8 6"/>'), "contact") +
    `<button class="micbtn ${G.live ? "oncall" : "pulse"}" data-act2="mic" aria-label="${G.live ? "End conversation" : "Start conversation"}">${G.live ? '<svg width="26" height="26" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="6" width="12" height="12" rx="2"/></svg>' : mic(28)}</button>` +
    tab("board", "Opportunities", I('<rect x="3" y="4" width="5" height="16" rx="1"/><rect x="10" y="4" width="5" height="11" rx="1"/><rect x="17" y="4" width="4" height="7" rx="1"/>'), "opp") +
    tab("tasks", "Tasks", I('<path d="M9 11l3 3 8-8"/><path d="M20 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>'));
}

document.addEventListener("input", (e) => { if (!["cSearch", "oSearch", "tSearch"].includes(e.target.id)) return; const q = e.target.value.trim().toLowerCase();
  const words = q.split(/\s+/).filter(Boolean);
  document.querySelectorAll("main [data-name]").forEach(row => { row.style.display = words.every(w => row.dataset.name.includes(w)) ? "" : "none"; });
  document.querySelectorAll("main .lgroup").forEach(h => { let n = h.nextElementSibling, any = false; while (n && !n.classList.contains("lgroup")) { if (n.dataset.name && n.style.display !== "none") any = true; n = n.nextElementSibling; } h.style.display = any ? "" : "none"; }); });
document.addEventListener("click", (e) => {
  const cl = e.target.closest("[data-call]"); if (cl) { placeCall(cl.dataset.call); return; }
  if (e.target.closest("#overlay") || e.target.closest("#modal")) return;
  const oi = e.target.closest("[data-oppid]"); if (oi) S.sel.opp = oi.dataset.oppid;
  const fm = e.target.closest("[data-form]"); if (fm && fm.dataset.form) { openForm(fm.dataset.form, fm.dataset.cid, fm.dataset.item); return; }
  const say = e.target.closest("[data-say]");
  if (say) { const line = say.dataset.say;
    if (line === "Walk me through the process" && !S.heardOverview) { S.heardOverview = true; save(); }
    if (/^Show me a list of contacts/.test(line)) { go("contacts"); return; }
    if (/^(Show me )?my opportunities/i.test(line)) { go("board"); return; }
    hintCard(say); return; }
  const mp = e.target.closest("[data-act2=mtgprep]"); if (mp) { ask(`"Prepare me for my meeting with ${mp.dataset.who}"`); return; } // the Prepare button sits inside the meeting row
  const ct = e.target.closest("[data-contact]"); if (ct) { S.sel.contact = ct.dataset.contact; go("contact"); tellPicked("contact"); return; }
  const op = e.target.closest("[data-opp]"); if (op) { S.sel.opp = op.dataset.opp; if (wide() && S.screen === "board" && (S.oppView || "list") === "list" && op.closest(".split-list")) { save(); render(); } else go("opp"); tellPicked("opp"); return; }
  const g = e.target.closest("[data-go]"); if (g) { if (g.dataset.go === "hfcheck") { go("home"); hfCheckModal(); return; } go(g.dataset.go); return; }
  const a = e.target.closest("[data-act2]"); if (!a) return;
  const act = a.dataset.act2;
  if (act === "mic") { if (G.live) endCall("officer tapped the mic"); else ask(null); }
  else if (act === "cultivate") { const o = oppById(S.sel.opp); if (o) { const t = { contact: contactById(o.contactId), opp: o }; V = { action: "cultivate", target: t, data: prefill("cultivate", {}, t), fromVoice: new Set() }; renderOverlay(); } }
  else if (act === "oppview") { S.oppView = a.dataset.v; save(); render(); }
  else if (act === "cfilt") { S.cFilter = a.dataset.v; save(); render(); }
  else if (act === "ofilt") { S.oFilter = a.dataset.v; save(); render(); }
  else if (act === "tfilt") { S.tFilter = a.dataset.v; save(); render(); }
  else if (act === "nafilt") { S.naFilter = a.dataset.v; save(); render(); }
  else if (act === "hfcheck") hfCheckModal();
  else if (act === "namore") { G.naOpen = G.naOpen || {}; G.naOpen[a.dataset.v] = true; render(); }
  else if (act === "flowhome") { S.flowBack = "home"; go("flow"); }
  else if (act === "flowstep") { const i = Number(a.dataset.i); S.flowAt = S.flowAt === i ? -1 : i; save(); render(); }
  else if (act === "flowat") { S.flowBack = "opp"; highlightStage(Math.max(0, flowIndex(a.dataset.stage))); }
  else if (act === "copylog") { const txt = VLOG.join("\n"); const done = () => toast("Log copied. Paste it to Claude.");
    (navigator.clipboard ? navigator.clipboard.writeText(txt).then(done) : Promise.reject()).catch(() => { const el = document.getElementById("vlogTxt"); el.value = txt; el.select(); try { document.execCommand("copy"); done(); } catch (x) { toast("Select the text and copy it."); } }); }
  else if (act === "copycall") { const txt = CALL_URL(); const done = () => toast("Start-up address copied. Paste it into the Shortcut.");
    (navigator.clipboard ? navigator.clipboard.writeText(txt).then(done) : Promise.reject()).catch(() => { const el = document.getElementById("callUrl"); el.select(); try { document.execCommand("copy"); done(); } catch (x) { toast("Select the address and copy it."); } }); }
  else if (act === "clearlog") { VLOG = []; try { localStorage.removeItem(LOGKEY); } catch (e) {} render(); toast("Log cleared"); }
  else if (act === "help") helpModal();
  else if (act === "saymore") { S.sayMore = !S.sayMore; save(); render(); }
  else if (act === "restartask") restartConfirm();
  else if (act === "share") shareDemo();
  else if (act === "qr") showQR();
  else if (act === "addbtnx") { S.settings.hideAddBtn = true; save(); render(); toast("Hidden. The steps are in Settings."); }
  else if (act === "quickadd") quickAdd();
  else if (act === "editname") { go("settings"); setTimeout(() => { const el = document.getElementById("userName"); if (el) { el.scrollIntoView({ block: "center" }); el.focus(); el.select(); } }, 60); }
  else if (act === "addbtn") { go("settings"); setTimeout(() => { const el = document.getElementById("setSave"); if (el) { el.scrollIntoView({ block: "start" }); el.classList.add("flash"); } }, 50); }
  else if (act === "hintson") { delete S.settings.noHints; save(); render(); toast("Hints are back on"); }
});
// Settings save as soon as a field changes (no Save buttons)
function saveName() { const el = document.getElementById("userName"); const v = el.value.trim().replace(/\s+/g, " ").slice(0, 60);
  if (!v) { el.value = S.settings.userName || ""; toast("Please enter your first name."); return; }
  if (v === S.settings.userName) return; S.settings.userName = v; save(); toast(`Saved. The assistant will call you ${v.split(" ")[0]}.`); }
function saveVoice() { const was = S.settings.voice + "|" + botName(); S.settings.voice = document.getElementById("voiceSel").value; S.settings.voicePicked = true; const bn = document.getElementById("botName").value.trim().replace(/\s+/g, " ").slice(0, 30); if (bn) S.settings.botName = bn; else delete S.settings.botName; save();
  if (was === S.settings.voice + "|" + botName()) return;
  // a new voice or name only takes hold in a new conversation (Grok keeps the voice, and what it already said, for the whole call)
  if (G.live) { endCall(); render(); toast(`Saved. Tap the mic to talk to ${botName()}.`); } else { const hl = document.querySelector('[data-act2="help"].linkbtn'); if (hl) hl.textContent = `How to talk to ${botName()} ›`; document.getElementById("botName").placeholder = botName(); toast(`Saved. The assistant's name is ${botName()}.`); } }
document.addEventListener("change", (e) => { const id = e.target.id;
  if (id === "f_permText" && V && ACTIONS[V.action].fields.some(f => f.when === "permText")) { V.data = readDraft(); const y = (document.querySelector(".sheet .sb") || {}).scrollTop; renderOverlay(); const sb = document.querySelector(".sheet .sb"); if (sb && y) sb.scrollTop = y; return; }
  if (id === "f_fund" && V && ACTIONS[V.action].fields.some(f => f.k === "campaign")) { V.data = prefill(V.action, readDraft(), V.target); delete V.data.badCampaign; const y = (document.querySelector(".sheet .sb") || {}).scrollTop; renderOverlay(); const sb = document.querySelector(".sheet .sb"); if (sb && y) sb.scrollTop = y; return; }
  if (id === "userName") saveName();
  else if (id === "voiceSel" || id === "botName") saveVoice();
  else if (id === "formVoiceSel") { S.settings.formVoice = e.target.value === "same" ? "same" : "leo"; save(); if (typeof TTS_CACHE !== "undefined") TTS_CACHE.clear(); toast(S.settings.formVoice === "same" ? `The app's own lines will use ${botName()}'s voice` : "The app's own lines will use Leo's voice"); }
  else if (id === "speedSel") { S.settings.speed = Number(e.target.value); save(); if (G.live) send({ type: "session.update", session: sessionCfg() }); toast(`Saved. ${botName()} will talk at ${speedName(talkSpeed())} speed.`); }
  else if (id === "spookyMode") { setSpooky(e.target.checked); if (G.live) send({ type: "session.update", session: sessionCfg() }); toast(e.target.checked ? "Spooky mode is on. Mwahaha! 🦇" : "Back to normal"); }
  else if (id === "xmasMode") { setXmas(e.target.checked); if (G.live) send({ type: "session.update", session: sessionCfg() }); toast(e.target.checked ? "Christmas mode is on. Ho ho ho! 🎄" : "Back to normal"); }
  else if (id === "xmasTgl") { if (e.target.checked) delete S.settings.noXmas; else S.settings.noXmas = true; save(); toast(e.target.checked ? "Merry Christmas! 🎄" : "Christmas visitors are off"); }
  else if (id === "spookyTgl") { if (e.target.checked) delete S.settings.noSpooky; else S.settings.noSpooky = true; save(); toast(e.target.checked ? "Happy Halloween! 🎃" : "Halloween visitors are off"); }
  else if (id === "locTgl") { const el = e.target;
    if (!el.checked) { delete S.settings.shareLocation; save(); locStop(); toast("Location is no longer recorded"); }
    else if (!navigator.geolocation) { el.checked = false; toast("This phone can't share its location"); }
    else navigator.geolocation.getCurrentPosition(pos => { S.settings.shareLocation = true; save(); G.pos = { lat: pos.coords.latitude, lon: pos.coords.longitude, acc: pos.coords.accuracy, at: Date.now() }; if (G.live) locStart(); toast("Location will be recorded in connection logs"); },
      err => { const t = document.getElementById("locTgl"); if (t) t.checked = false; toast("The phone didn't allow location" + (err && err.message ? " (" + err.message + ")" : "")); }, { enableHighAccuracy: true, timeout: 20000 }); }
  else if (id === "hintsTgl") { if (e.target.checked) delete S.settings.noHints; else S.settings.noHints = true; save(); toast(e.target.checked ? "Hints are on" : "Hints are off"); } });
document.addEventListener("keydown", (e) => { if (e.key === "Enter" && (e.target.id === "userName" || e.target.id === "botName")) e.target.blur(); });
function doRestart() { const keep = S.settings; if (G.live) endCall(); S = fresh(); seedActivity(S); S.seed2 = true; S.permFix1 = true; S.dataVersion = DATA_VERSION; S.settings.deviceId = keep.deviceId; S.settings.demoCode = keep.demoCode || ""; // a restart puts every setting back to its default (voice, assistant name, hints, first name); only the phone ID and code word stay
  save(); render(); welcomeModal(); toast("Proof of concept restarted"); }
function restartConfirm() {
  const h = document.getElementById("modal");
  h.innerHTML = `<div class="scrim center" data-helpx="1"><div class="wmodal hmodal" role="dialog" aria-modal="true" aria-labelledby="rsTitle">
    <h2 id="rsTitle">Restart the proof of concept?</h2>
    <p class="wl-hint">Everything you've added is removed and all settings go back to how they started. This can't be undone.</p>
    <button type="button" class="btn red" id="rsGo">Yes, restart</button><button type="button" class="btn quiet" data-helpx="1">Cancel</button></div></div>`;
  document.getElementById("rsGo").onclick = () => { h.innerHTML = ""; doRestart(); };
}
document.addEventListener("keydown", (e) => { if ((e.key === "Enter" || e.key === " ") && e.target.matches && e.target.matches("[role=button][tabindex]")) { e.preventDefault(); e.target.click(); } });
